        if i < len(tokens) and tokens[i] not in ("null", "None", "#"):
            node.left = TreeNode(int(tokens[i]))
            q.append(node.left)
        i += 1
        if i < len(tokens) and tokens[i] not in ("null", "None", "#"):
            node.right = TreeNode(int(tokens[i]))
            q.append(node.right)
        i += 1
    return root

def level_order(root):
    out, q = [], deque([root]) if root else deque()
    while q:
        node = q.popleft()
        out.append(str(node.val))
        if node.left:
            q.append(node.left)
        if node.right:
            q.append(node.right)
    return out

def main():
