import sys

def main():
    data = sys.stdin.read().split()
    p = 0
    n, m = int(data[p]), int(data[p + 1]); p += 2
    parent = list(range(n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for _ in range(m):
        u, v = int(data[p]), int(data[p + 1]); p += 2
        ru, rv = find(u), find(v)
        if ru == rv:
            print(u, v)          # 冗余连接：这条边让图成环
            return
        parent[ru] = rv

if __name__ == "__main__":
    main()
